{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Investment — Pricing | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7faf6;--ink:#0b2b2a;--muted:#5a6b68;--accent:#7aa89f;--card:#ffffff;--glass:rgba(255,255,255,0.6);--shadow:0 6px 24px rgba(10,20,18,0.06);font-family:Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#eef6f3);color:var(--ink);line-height:1.45}
    header{display:flex;align-items:center;justify-content:space-between;padding:28px 40px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:54px;height:54px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#92c7b6);display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-size:15px}
    .hero{max-width:1100px;margin:28px auto 20px;padding:42px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--card));box-shadow:var(--shadow);position:relative;overflow:hidden}
    .pattern{position:absolute;right:-60px;top:-40px;opacity:0.08;width:420px;height:420px}
    h1{margin:0 0 10px;font-size:28px;letter-spacing:-0.02em}
    p.lead{margin:0;color:var(--muted);max-width:72ch}
    .split{display:flex;gap:28px;margin-top:26px}
    .panel{flex:1;background:var(--card);padding:18px;border-radius:10px;box-shadow:0 6px 18px rgba(8,18,17,0.04)}
    .moods{display:flex;gap:10px;flex-wrap:wrap}
    .mood{padding:10px 14px;border-radius:10px;background:transparent;border:1px solid rgba(10,20,18,0.06);cursor:pointer;color:var(--muted)}
    .mood.active{background:linear-gradient(90deg,rgba(122,168,159,0.12),rgba(146,199,182,0.12));border-color:transparent;color:var(--ink);font-weight:600}
    .recommended{padding:10px;border-radius:8px;background:linear-gradient(180deg,rgba(122,168,159,0.06),rgba(255,255,255,0.6));border:1px solid rgba(122,168,159,0.12)}
    .cta{display:inline-block;margin-top:14px;padding:12px 18px;border-radius:10px;background:var(--accent);color:white;text-decoration:none;font-weight:600}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow);border:1px solid rgba(10,20,18,0.03)}
    .price{font-size:22px;font-weight:700;color:var(--ink)}
    .meta{color:var(--muted);font-size:14px}
    .timeline{margin-top:22px;padding:16px;border-radius:10px;background:linear-gradient(180deg,white,rgba(240,252,248,0.9));border:1px solid rgba(122,168,159,0.06)}
    .phases{display:flex;gap:10px}
    .phase{flex:1;padding:12px;border-radius:8px;border:1px solid rgba(10,20,18,0.04);background:transparent;cursor:pointer}
    .phase.active{background:linear-gradient(90deg,rgba(122,168,159,0.08),rgba(146,199,182,0.08));border-color:rgba(122,168,159,0.12)}
    .disclaimer{margin-top:12px;color:var(--muted);font-size:13px}
    footer{max-width:1100px;margin:40px auto;padding:18px;text-align:center;color:var(--muted)}
    @media (max-width:900px){.split{flex-direction:column}.grid{grid-template-columns:1fr}.pattern{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Roots</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Concerns</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Story</a>
      <a href="book.html">Begin</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="hero">
    <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden>
      <defs>
        <pattern id="p1" width="20" height="20" patternUnits="userSpaceOnUse">
          <rect width="20" height="20" fill="transparent"/>
          <path d="M0 10h20M10 0v20" stroke="#7aa89f" stroke-opacity="0.12" stroke-width="1"/>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#p1)"/>
    </svg>

    <h1>Investment in layered wellbeing</h1>
    <p class="lead">Care that weaves clinical guidance, lifestyle practices, and gentle therapies into a clear sequence. Choose a starting state below — we will suggest a path and a fitting offering.</p>

    <div class="split">
      <div class="panel">
        <div style="font-size:13px;color:var(--muted)">Where are you now?</div>
        <div class="moods" id="moodList">
          <button class="mood" data-key="low_energy">Low energy</button>
          <button class="mood" data-key="stressed">Stressed / tense</button>
          <button class="mood" data-key="cloudy">Mental fog</button>
          <button class="mood" data-key="seeking">Seeking rhythm</button>
          <button class="mood" data-key="curious">Curious about change</button>
        </div>

        <div style="margin-top:14px;font-size:13px;color:var(--muted)">Suggested approach</div>
        <div class="recommended" id="recommended">
          <div style="font-weight:700">Balanced Mini-Track</div>
          <div style="margin-top:6px;color:var(--muted);font-size:14px">A short, guided introduction with a focused consult and two follow-ups to orient habits and priorities.</div>
          <a id="primaryCta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>

      <div style="flex:1">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-size:13px;color:var(--muted)">Offer frames</div>
            <div style="font-weight:700;font-size:18px">Programs tailored for stepwise change</div>
          </div>
          <div style="text-align:right;color:var(--muted);font-size:13px">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        </div>

        <div class="grid">
          <div class="card">
            <div style="font-size:13px;color:var(--muted)">Starter</div>
            <div class="price">$295</div>
            <div class="meta">Initial consult + personalized guide (60–75 min)</div>
            <div style="margin-top:10px;color:var(--muted);font-size:14px">For someone seeking a clear first step and home plan.</div>
          </div>

          <div class="card">
            <div style="font-size:13px;color:var(--muted)">Renew Track</div>
            <div class="price">$780</div>
            <div class="meta">3 sessions across 10–12 weeks</div>
            <div style="margin-top:10px;color:var(--muted);font-size:14px">A paced series to support new rhythms and accountable micro-steps.</div>
          </div>

          <div class="card">
            <div style="font-size:13px;color:var(--muted)">Foundations Plan</div>
            <div class="price">$1,600</div>
            <div class="meta">6-session roadmap + check-ins</div>
            <div style="margin-top:10px;color:var(--muted);font-size:14px">A full phase-based plan for layered change and measurable practice.</div>
          </div>
        </div>

        <div class="timeline" id="timeline">
          <div style="font-weight:700">A gentle roadmap</div>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">Select phases to build a bespoke sequence. Phases are educational and supportive — not a substitute for medical treatment.</div>
          <div class="phases" style="margin-top:12px">
            <button class="phase" data-phase="1">Phase 1 — Recalibrate
              <div style="font-size:12px;color:var(--muted);margin-top:6px">Assessment, simple routines, clarity of priorities.</div>
            </button>
            <button class="phase" data-phase="2">Phase 2 — Integrate
              <div style="font-size:12px;color:var(--muted);margin-top:6px">Tailored sessions, habit integration, practical tools.</div>
            </button>
            <button class="phase" data-phase="3">Phase 3 — Sustain
              <div style="font-size:12px;color:var(--muted);margin-top:6px">Check-ins, refinement, planning for maintenance.</div>
            </button>
          </div>

          <div class="disclaimer">
            Note: The timeline is a planning tool. It offers educational guidance and is not medical advice. If you have urgent or complex health needs, consult your clinician.
          </div>
        </div>

      </div>
    </div>
  </main>

  <footer>
    <div>Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</div>
    <div style="margin-top:8px;color:var(--muted);font-size:13px">Serving {{CITY}}, {{STATE}} • Care framed with clinical insight and lifestyle practice.</div>
  </footer>

  <script>
    (function(){
      const moods = document.querySelectorAll('.mood');
      const recommended = document.getElementById('recommended');
      const cta = document.getElementById('primaryCta');

      const map = {
        low_energy: {title:'Renew Mini-Track',desc:'Short course to lift daily energy: a focused consult, sleep and nutrition micro-plan, and one follow-up.',cta:'Begin Renew Mini-Track'},
        stressed: {title:'Calm Sequence',desc:'Stress-focused pathway with grounding practices, breathwork guidance, and two guided sessions.',cta:'Begin Calm Sequence'},
        cloudy: {title:'Clarity Series',desc:'Work to clear cognitive fog: assessment, targeted practices, and habit scaffolding.',cta:'Begin Clarity Series'},
        seeking: {title:'Rhythm Builder',desc:'A paced plan to craft consistent routines: planning, practice, and accountability.',cta:'Begin Rhythm Builder'},
        curious: {title:'Intro Consult',desc:'A consult and bespoke recommendations to orient next steps; good if you want to explore options.',cta:'Book an Intro Consult'}
      };

      function setActive(key){
        moods.forEach(b=>b.classList.toggle('active',b.dataset.key===key));
        const info = map[key] || map['curious'];
        recommended.querySelector('div').textContent = info.title;
        recommended.querySelector('div + div').textContent = info.desc;
        cta.textContent = info.cta;
        // update href with query to help analytics
        const url = new URL('{{PRIMARY_CTA_URL}}', location.href);
        url.searchParams.set('starter', key);
        cta.setAttribute('href', url.toString());
      }

      moods.forEach(b=>b.addEventListener('click',()=>setActive(b.dataset.key)));
      // default
      setActive('curious');

      // timeline interactive
      const phases = document.querySelectorAll('.phase');
      phases.forEach(p=>p.addEventListener('click',()=>{
        p.classList.toggle('active');
      }));

    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Story — About | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffefb;--ink:#072322;--muted:#4f6a65;--accent:#b2d6cc;--card:#ffffff;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#eef7f4);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 36px}
    .logo{height:46px;width:46px;border-radius:10px;background:linear-gradient(135deg,#9fc6b6,#bfece1);display:grid;place-items:center;color:#013232;font-weight:700}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none}
    .hero{max-width:980px;margin:20px auto;padding:32px;border-radius:12px;background:rgba(255,255,255,0.9);box-shadow:0 10px 30px rgba(6,18,16,0.04);position:relative}
    .svgwrap{position:absolute;left:-40px;top:-40px;opacity:0.08;width:360px;height:360px}
    h1{margin:0;font-size:26px}
    p.lead{color:var(--muted);max-width:66ch}
    .content{display:grid;grid-template-columns:320px 1fr;gap:20px;margin-top:18px}
    .bio{background:var(--card);padding:16px;border-radius:10px;box-shadow:0 6px 18px rgba(6,18,16,0.04)}
    .values{padding:12px}
    .timeline{margin-top:18px;padding:16px;border-radius:10px;background:linear-gradient(180deg,#fff,#f1fbf7);border:1px solid rgba(123,179,164,0.06)}
    .phases{display:flex;flex-direction:column;gap:10px}
    .phase{padding:10px;border-radius:8px;border-left:4px solid rgba(123,179,164,0.16);background:transparent}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:8px;background:var(--accent);color:#022; text-decoration:none;font-weight:600}
    footer{max-width:980px;margin:32px auto;text-align:center;color:var(--muted);font-size:13px}
    @media (max-width:900px){.content{grid-template-columns:1fr}.svgwrap{display:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Roots</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Concerns</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Story</a>
      <a href="book.html">Begin</a>
    </nav>
  </header>

  <main class="hero">
    <svg class="svgwrap" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden>
      <defs>
        <linearGradient id="g2" x1="0" x2="1">
          <stop offset="0" stop-color="#bfece1" stop-opacity="0.9" />
          <stop offset="1" stop-color="#9fc6b6" stop-opacity="0.9" />
        </linearGradient>
        <pattern id="q1" width="40" height="40" patternUnits="userSpaceOnUse">
          <rect width="40" height="40" fill="transparent"/>
          <circle cx="20" cy="20" r="2" fill="#0b3b37" fill-opacity="0.06"/>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#q1)"/>
      <circle cx="160" cy="40" r="60" fill="url(#g2)" fill-opacity="0.12"/>
    </svg>

    <h1>We listen to your whole map</h1>
    <p class="lead">A small practice that pairs clinical context with daily practices — offered with humility and curiosity. Our invitations are educational and optional; they are not a promise of cure.</p>

    <div class="content">
      <aside class="bio">
        <div style="font-weight:700">Our approach</div>
        <div style="margin-top:8px;color:var(--muted);font-size:14px">We combine thorough intake, targeted supports, and practical micro-habits so you can try changes that fit your life. Plans are co-created and revisited.</div>

        <div style="margin-top:14px" class="values">
          <div style="font-weight:700;font-size:13px">Principles</div>
          <ul style="margin:8px 0 0 18px;color:var(--muted)">
            <li>Listen first — prioritize what matters to you</li>
            <li>Small experiments over sweeping promises</li>
            <li>Evidence-informed, person-centered</li>
          </ul>
        </div>
      </aside>

      <section>
        <div style="font-weight:700">A brief timeline of care design</div>
        <div class="timeline">
          <div style="font-size:13px;color:var(--muted)">These are typical phases we use when planning work with clients. They are educational and adaptable.</div>
          <div class="phases">
            <div class="phase">
              <strong>Phase 1 — Clarify</strong>
              <div style="color:var(--muted);font-size:13px;margin-top:6px">Detailed intake, screening, and identification of the most helpful next steps.</div>
            </div>

            <div class="phase">
              <strong>Phase 2 — Practice</strong>
              <div style="color:var(--muted);font-size:13px;margin-top:6px">Short, focused sessions with habit scaffolding and simple daily tasks to test what helps.</div>
            </div>

            <div class="phase">
              <strong>Phase 3 — Embed</strong>
              <div style="color:var(--muted);font-size:13px;margin-top:6px">Periodic check-ins and adjustment to help sustain practices that feel useful.</div>
            </div>
          </div>

          <div style="margin-top:12px;color:var(--muted);font-size:13px">Disclaimer: This timeline is a planning guide and not a substitute for medical care. If your needs are urgent or complex, consult your primary clinician.</div>
        </div>

        <div style="margin-top:18px">
          <div style="font-weight:700">Who we serve</div>
          <p style="color:var(--muted);max-width:60ch">People who want a structured, compassionate way to try lifestyle and therapeutic supports alongside their other care. We do not promise cures — we offer guidance, skills, and measured plans to help you explore change.</p>
        </div>

        <a id="aboutCta" class="cta" href="{{PRIMARY_CTA_URL}}">Start a conversation</a>
      </section>
    </div>
  </main>

  <footer>
    <div>Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{PHONE}}</div>
    <div style="margin-top:6px;color:var(--muted)">Serving {{CITY}}, {{STATE}} — appointments by request.</div>
  </footer>

  <script>
    // Small mood-to-method on About to nudge folks toward booking
    (function(){
      const cta = document.getElementById('aboutCta');
      const choices = [
        {label:'Feeling drained',cta:'Book a Renewal Consult',q:'low_energy'},
        {label:'Tight and anxious',cta:'Book a Soothing Consult',q:'stressed'},
        {label:'Curious about options',cta:'Book a Discovery Visit',q:'curious'}
      ];

      // Build a tiny selector
      const wrap = document.createElement('div');
      wrap.style.marginTop = '14px';
      wrap.style.display = 'flex';
      wrap.style.gap = '10px';

      choices.forEach(ch=>{
        const b = document.createElement('button');
        b.textContent = ch.label;
        b.style.padding = '8px 10px'; b.style.borderRadius = '8px'; b.style.border='1px solid rgba(2,35,33,0.06)'; b.style.background='white'; b.style.cursor='pointer'; b.style.color='var(--muted)';
        b.addEventListener('click',()=>{
          cta.textContent = ch.cta;
          const url = new URL('{{PRIMARY_CTA_URL}}', location.href);
          url.searchParams.set('starter', ch.q);
          cta.href = url.toString();
          // subtle highlight
          b.style.background = 'linear-gradient(90deg,#dbeee5,#f7fffb)';
        });
        wrap.appendChild(b);
      });

      const hero = document.querySelector('.hero section');
      hero.insertBefore(wrap, hero.querySelector('.cta'));
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Begin — Book a Visit | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f4f9f6;--ink:#053231;--muted:#48645f;--accent:#8fc6b3;--card:#ffffff;font-family:Inter,system-ui,Arial}
    body{margin:0;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 36px}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,#8fc6b3,#bfece1);display:grid;place-items:center;color:#053231;font-weight:700}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    .wrap{max-width:900px;margin:22px auto;padding:20px;background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff);border-radius:12px;box-shadow:0 10px 30px rgba(6,18,16,0.04);position:relative}
    .pattern{position:absolute;right:-20px;bottom:-40px;opacity:0.06;width:320px;height:320px}
    h1{margin:0;font-size:24px}
    p.lead{color:var(--muted);margin-top:8px}
    form{display:grid;grid-template-columns:1fr 260px;gap:18px;margin-top:18px}
    .panel{background:var(--card);padding:14px;border-radius:10px}
    label{display:block;font-size:13px;color:var(--muted);margin-bottom:6px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(5,50,45,0.08);font-size:14px}
    textarea{min-height:120px}
    .right{display:flex;flex-direction:column;gap:12px}
    .session{padding:12px;border-radius:10px;border:1px solid rgba(5,50,45,0.06)}
    .session.selected{background:linear-gradient(90deg,rgba(143,198,179,0.08),rgba(191,236,225,0.08));border-color:rgba(143,198,179,0.12)}
    .bookBtn{display:inline-block;padding:12px 16px;border-radius:10px;background:var(--accent);color:#042; text-decoration:none;font-weight:700;margin-top:8px}
    .note{color:var(--muted);font-size:13px}
    .timeline{margin-top:14px;padding:12px;border-radius:8px;background:linear-gradient(180deg,#fff,#f3fbf8);border:1px solid rgba(143,198,179,0.06)}
    footer{max-width:900px;margin:26px auto;text-align:center;color:var(--muted)}
    @media (max-width:880px){form{grid-template-columns:1fr} .pattern{display:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Roots</a>
      <a href="services.html">Offerings</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Story</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden>
      <defs>
        <pattern id="r1" width="24" height="24" patternUnits="userSpaceOnUse">
          <rect width="24" height="24" fill="transparent"/>
          <path d="M0 12h24" stroke="#8fc6b3" stroke-opacity="0.08" stroke-width="1"/>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#r1)"/>
    </svg>

    <h1>Begin: book a first visit</h1>
    <p class="lead">Choose a session structure that matches what you want to explore. If you are unsure, use the Mood-to-Method helper to shape a suggestion.</p>

    <form id="bookForm" action="{{PRIMARY_CTA_URL}}" method="get">
      <div>
        <div class="panel">
          <label for="name">Name</label>
          <input id="name" name="name" placeholder="Your name" required />

          <label for="email" style="margin-top:10px">Email</label>
          <input id="email" name="email" type="email" placeholder="you@domain.com" required />

          <label for="note" style="margin-top:10px">A short note (concern, goals, or context)</label>
          <textarea id="note" name="note" placeholder="A few lines about what brings you here"></textarea>

          <div style="margin-top:12px">
            <label style="margin-bottom:6px">Mood-to-Method</label>
            <div style="display:flex;gap:8px;flex-wrap:wrap" id="moodButtons">
              <button type="button" class="moodBtn" data-key="low_energy">Low energy</button>
              <button type="button" class="moodBtn" data-key="stressed">Tense</button>
              <button type="button" class="moodBtn" data-key="curious">Curious</button>
              <button type="button" class="moodBtn" data-key="focus">Need focus</button>
            </div>
          </div>
        </div>
      </div>

      <aside class="right">
        <div class="panel">
          <div style="font-weight:700">Session types</div>
          <div style="margin-top:10px;display:flex;flex-direction:column;gap:10px">
            <div class="session" data-id="intro">
              <div style="font-weight:700">Discovery Visit — $95</div>
              <div class="note">30 min. Clarify priorities and next steps.</div>
            </div>
            <div class="session" data-id="standard">
              <div style="font-weight:700">Standard Consult — $295</div>
              <div class="note">60–75 min. Intake and a practical plan to try for the next 2–6 weeks.</div>
            </div>
            <div class="session" data-id="series">
              <div style="font-weight:700">Series Check — $780</div>
              <div class="note">Package of 3 visits for a paced plan and accountability.</div>
            </div>
          </div>

          <div class="timeline">
            <div style="font-weight:700">Booking roadmap</div>
            <div style="color:var(--muted);font-size:13px;margin-top:6px">After booking, you will receive an intake form and pre-visit notes. We recommend a light preparatory questionnaire to focus our time together.</div>
            <div style="margin-top:8px;color:var(--muted);font-size:13px">Disclaimer: This process is informational. It is not medical advice and does not replace your primary clinician.</div>
          </div>

          <input type="hidden" name="starter" id="starterField" value="" />
          <a id="bookNow" class="bookBtn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </aside>
    </form>
  </main>

  <footer>
    <div>Questions before booking? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{PHONE}}</div>
    <div style="margin-top:6px;color:var(--muted)">Appointments available in {{CITY}}, {{STATE}} and virtual sessions where appropriate.</div>
  </footer>

  <script>
    (function(){
      // mood-to-method logic
      const map = {
        low_energy:{session:'standard',starter:'low_energy',cta:'Book a Standard Consult'},
        stressed:{session:'standard',starter:'stressed',cta:'Book a Soothing Consult'},
        curious:{session:'intro',starter:'curious',cta:'Book a Discovery Visit'},
        focus:{session:'series',starter:'focus',cta:'Book a Series Check'}
      };

      const moodButtons = document.querySelectorAll('.moodBtn');
      const sessions = document.querySelectorAll('.session');
      const bookNow = document.getElementById('bookNow');
      const starterField = document.getElementById('starterField');

      function clearSelected(){
        sessions.forEach(s=>s.classList.remove('selected'));
      }

      function selectSessionById(id){
        clearSelected();
        const target = [...sessions].find(s=>s.dataset.id===id);
        if(target) target.classList.add('selected');
      }

      moodButtons.forEach(b=>{
        b.style.padding='8px 10px'; b.style.border='1px solid rgba(5,50,45,0.06)'; b.style.background='white'; b.style.borderRadius='8px'; b.style.cursor='pointer'; b.addEventListener('click',()=>{
          moodButtons.forEach(x=>x.style.background='white');
          b.style.background='linear-gradient(90deg,#dff5ee,#f7fffb)';
          const key = b.dataset.key;
          const info = map[key] || map['curious'];
          selectSessionById(info.session);
          bookNow.textContent = info.cta;
          bookNow.href = (new URL('{{PRIMARY_CTA_URL}}', location.href)).toString() + '?starter=' + info.starter;
          starterField.value = info.starter;
        });
      });

      // let clicking session set as selection and update CTA
      sessions.forEach(s=>s.addEventListener('click',()=>{
        const id = s.dataset.id;
        selectSessionById(id);
        // map selection to CTA
        let cta = 'Book';
        if(id==='intro') cta='Book a Discovery Visit';
        if(id==='standard') cta='Book a Standard Consult';
        if(id==='series') cta='Book a Series Check';
        bookNow.textContent = cta;
        bookNow.href = (new URL('{{PRIMARY_CTA_URL}}', location.href)).toString() + '?session=' + id;
        starterField.value = id;
      }));

      // default selection
      selectSessionById('standard');
      bookNow.textContent = '{{PRIMARY_CTA_LABEL}}';
      bookNow.href = '{{PRIMARY_CTA_URL}}';

    })();
  </script>
</body>
</html>"} 
